import {nodes,endings} from './story.js';
const $=id=>document.getElementById(id);let path='',sound=true,audioUnlocked=false,ctx,timer,full='',typing=false,locked=false;let seen=new Set();try{seen=new Set(JSON.parse(localStorage.getItem('ttekoto-pilot-endings')||'[]'))}catch{}
function tone(freq=600,duration=.045,delay=0){if(!sound||!audioUnlocked)return;try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,ctx.currentTime+delay);o.frequency.exponentialRampToValueAtTime(freq*.75,ctx.currentTime+delay+duration);g.gain.setValueAtTime(.045,ctx.currentTime+delay);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+delay+duration);o.connect(g).connect(ctx.destination);o.start(ctx.currentTime+delay);o.stop(ctx.currentTime+delay+duration)}catch{}}
function finishText(){clearInterval(timer);$('line').textContent=full;typing=false;$('skip').hidden=true;}
function write(text){clearInterval(timer);full=text;$('line').textContent='';typing=true;$('skip').hidden=false;let i=0;timer=setInterval(()=>{i++;$('line').textContent=full.slice(0,i);if(i%3===0)tone(530+Math.random()*100);if(i>=full.length)finishText()},28)}
function button(label,fn,primary=false){const b=document.createElement('button');b.className='choice'+(primary?' primary':'');b.textContent=label;b.onclick=fn;return b}
function render(){locked=false;const end=endings[path],n=end||nodes[path];$('game').classList.toggle('ending',!!end);$('scene').className='scene '+n.mood;$('reaction').textContent=n.voice;$('caption').textContent=end?n.genre:n.caption;$('speaker').textContent=end?'おはなし '+(parseInt(path,2)+1).toString().padStart(2,'0')+' / 08':'ちいかわ';$('progress').innerHTML=[0,1,2].map(i=>'<span class="dot '+(i<path.length?'active':'')+'"></span>').join('');$('choices').replaceChildren();document.querySelector('.ending-title')?.remove();if(end){seen.add(path);try{localStorage.setItem('ttekoto-pilot-endings',JSON.stringify([...seen]))}catch{}const h=document.createElement('h2');h.className='ending-title';h.textContent=end.title+(end.truth?' ◎':'');$('line').before(h);$('choices').append(button('別の「ってコト⁉︎」をためす',()=>{path='';render()},true),button('ひとつ前の選択に戻る',()=>{path=path.slice(0,-1);render()}));}else{n.choices.forEach((text,i)=>{const b=button('',()=>choose(i));b.append(document.createTextNode(text));const s=document.createElement('small');s.textContent='…ってコト⁉︎';b.append(s);$('choices').append(b)});}write(n.line);$('collection').textContent='おはなし '+seen.size+' / 8';if(sound){tone(n.mood==='fear'?390:780,.12);tone(n.mood==='happy'?990:570,.14,.16)}}
function choose(i){if(locked)return;locked=true;finishText();$('speaker').textContent='ハチワレ';$('line').textContent=nodes[path].choices[i]+'…ってコト⁉︎';$('reaction').textContent='…ってコト⁉︎';tone(850,.1);for(const b of $('choices').children)b.disabled=true;setTimeout(()=>{path+=i;render()},650)}
$('sound').textContent='音 ON';$('sound').setAttribute('aria-pressed','true');
document.addEventListener('click',event=>{audioUnlocked=true;if(sound&&event.target.closest?.('#sound')==null)tone();},{capture:true,once:true});
$('sound').onclick=()=>{audioUnlocked=true;sound=!sound;$('sound').textContent='音 '+(sound?'ON':'OFF');$('sound').setAttribute('aria-pressed',String(sound));tone()};$('skip').onclick=finishText;$('restart').onclick=()=>{if(locked)return;path='';render()};document.addEventListener('visibilitychange',()=>{if(document.hidden){finishText();ctx?.suspend()}else if(sound)ctx?.resume()});render();
